export const siteData = {
  profile: {
    name: "Kelvin Li",
    description: (
      <>
        4th year undergraduate at UC Berkeley studying EECS and Mathematics.
        Incoming EECS 5th year M.S. Advised by{" "}
        <a
          href="https://roeiherz.github.io/"
          target="_blank"
          rel="noopener noreferrer"
          className="underline underline-offset-2 hover:text-neutral-600"
        >
          Roei Herzig
        </a>{" "}
        and{" "}
        <a
          href="https://people.eecs.berkeley.edu/~trevor/"
          target="_blank"
          rel="noopener noreferrer"
          className="underline underline-offset-2 hover:text-neutral-600"
        >
          Prof. Trevor Darrell
        </a>
        .
      </>
    ),
  },

  socialLinks: [
    {
      label: "Email",
      href: "mailto:kelvin.li.jm@gmail.com",
    },
    {
      label: "LinkedIn",
      href: "https://www.linkedin.com/in/kelvin-li-jm/",
    },
    {
      label: "Google Scholar",
      href: "https://scholar.google.com/",
    },
  ],

  publications: [
    {
      id: "livr-cvpr-2026",
      title: "Latent Implicit Visual Reasoning",
      venue: "CVPR, 2026",
      authors: [
        { name: "Kelvin Li", equal: true },
        { name: "Chuyi Shang", equal: true },
        { name: "Leonid Karlinsky" },
        { name: "Rogerio Feris" },
        { name: "Trevor Darrell" },
        { name: "Roei Herzig" },
      ],
      links: [
        {
          label: "arXiv",
          href: "https://arxiv.org/abs/2512.21218",
        },
      ],
      image: "/images/livr_teaser.png",
      note: "** equal contribution",
    },
  ],
};
